    "notas": [
      "Sacado del timeline de Hudl (el etiquetado de Wyscout del partido), no mirando imagen a imagen: salen TODOS los robos del partido.",
      "Cuenta como robo la interceptación, el duelo defensivo que acaba con el balón nuestro y la recuperación con el rival presionado o tras nuestra pérdida. No cuentan las del portero, las que vienen de un despeje, un rechace o un balón parado del rival, ni las faltas pitadas.",
      "El segundo es el del vídeo táctico del club, atado al de Hudl por tramos medidos jugada a jugada.",
      "La cámara táctica de este partido es una cámara lateral desde la grada principal (la de los banquillos) que panea con el juego, no un dron fijo: no siempre salen los 22.",
      "Desfase táctica − Hudl: +2 s constante en todo el partido (medido en el saque inicial, los dos goles, el inicio de la 2ª parte, cuatro córners y la falta directa del 86). No se ha visto ningún corte; los dos vídeos duran casi lo mismo (5716 y 5719 s) y los dos quitan el descanso.",
      "Sentido de ataque (igual en la TV y en la táctica, las dos desde la grada de los banquillos): 1ª parte el Castilla ataca hacia la DERECHA de la pantalla y el Ibiza hacia la izquierda; 2ª parte al revés.",
      "Castilla de verde oscuro con dorsal blanco (portero Mestre de naranja); UD Ibiza de celeste (portero Prieto de naranja/rojo). En el marcador de la TV: IBZ = Ibiza, CAS = Castilla."
    ],
